<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {api,listArtifacts,downloadArtifact} from '../api'
import ArtifactPreview from './ArtifactPreview.vue'
const props=defineProps<{runId:string;status:string;answer:string}>(),emit=defineEmits<{(e:'retried',id:string):void}>()
type Row=Record<string,any>
const open=ref(false),tab=ref('plan'),revision=ref(0),steps=ref<Row[]>([]),actual=ref<Row[]>([]),permissions=ref<Row[]>([]),files=ref<Row[]>([]),batches=ref<Row[]>([]),sources=ref<Row>({}),error=ref(''),busy=ref(false),newStep=ref(''),preview=ref<Row|null>(null),confirmBatch=ref('')
const uploading=ref(false),uploadNotice=ref('')
const format=ref('docx'),title=ref('任务报告'),content=ref(''),exporting=ref(false)
let version=0,timer:ReturnType<typeof setInterval>|undefined,dirty=false
const terminal=()=>['succeeded','failed','cancelled','timed_out','budget_exceeded'].includes(props.status)
function parse(value:string){try{return JSON.parse(value)}catch{return []}}
async function refresh(){if(!open.value||!props.runId)return;const v=++version,id=props.runId;try{const [p,s,g,a,b,c]=await Promise.all([api.get<Row>(`/api/operations/runs/${id}/plan`),api.get<Row>(`/api/operations/runs/${id}/steps`),api.get<Row>(`/api/operations/runs/${id}/permissions`),listArtifacts(id),api.get<Row>(`/api/operations/runs/${id}/batches`),api.get<Row>(`/api/operations/runs/${id}/sources`)]);if(v!==version)return;if(!dirty){revision.value=p.revision;steps.value=p.steps}actual.value=s.steps;permissions.value=g.permissions;files.value=a;batches.value=b.batches;sources.value=c;error.value=''}catch(e){if(v===version)error.value=(e as Error).message}}
async function act(action:()=>Promise<unknown>){if(busy.value)return;busy.value=true;try{await action();dirty=false;await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function save(){await act(()=>api.put(`/api/operations/runs/${props.runId}/plan`,{revision:revision.value,steps:steps.value}))}
function add(){if(!newStep.value.trim())return;steps.value.push({id:crypto.randomUUID(),title:newStep.value.trim(),status:'pending'});newStep.value='';dirty=true}
function move(index:number){if(index<1||steps.value[index-1]?.status!=='pending')return;const current=steps.value[index]!;steps.value[index]=steps.value[index-1]!;steps.value[index-1]=current;dirty=true}
async function retry(id:string){await act(async()=>{const r=await api.post<Row>(`/api/operations/runs/${props.runId}/retry`,{stepId:id});emit('retried',r.runId)})}
async function uploadFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const run=props.runId;uploading.value=true;uploadNotice.value='';try{if(file.size>20_000_000)throw new Error('资料文件不能超过20MB');await api.upload(`/api/file-tools/runs/${run}/upload`,file);if(run===props.runId){uploadNotice.value='资料已保存。可以在输入框中说明用途，后续任务会从本会话查找文件。';await refresh()}}catch(e){if(run===props.runId)error.value=(e as Error).message}finally{input.value='';uploading.value=false}}
async function exportFile(){if(exporting.value)return;exporting.value=true;try{await api.post(`/api/operations/runs/${props.runId}/export`,{format:format.value,title:title.value,content:content.value});await refresh()}catch(e){error.value=(e as Error).message}finally{exporting.value=false}}
watch(()=>props.runId,()=>{version++;dirty=false;uploadNotice.value='';confirmBatch.value='';steps.value=[];files.value=[];refresh()})
watch(open,value=>{if(value){content.value=props.answer;refresh();timer=setInterval(()=>{if(!busy.value&&!terminal())refresh()},5000)}else{version++;clearInterval(timer)}})
watch(()=>props.answer,value=>{if(!content.value)content.value=value})
onBeforeUnmount(()=>{version++;clearInterval(timer)})
const statusLabel=(value:string)=>({pending:'待执行',doing:'执行中',done:'已完成',failed:'失败',skipped:'已跳过',running:'执行中',succeeded:'成功',cancelled:'已停止'} as Record<string,string>)[value]||value
const scopeLabel=(scope:string)=>({network:'互联网访问',command:'主机终端命令',browser:'浏览器交互',sandbox:'隔离终端命令'} as Record<string,string>)[scope]||scope
</script>
<template><section class="run-workspace" :data-run-id="runId"><button class="workspace-toggle" :aria-expanded="open" @click="open=!open"><span>任务工作台</span><small>计划 · 文件与导出 · 来源 · 授权</small><span>{{ open?'收起':'展开' }}</span></button><div v-if="open" class="workspace-body"><nav><button v-for="item in [{id:'plan',title:'任务计划'},{id:'files',title:'文件与成果'},{id:'sources',title:'知识来源'},{id:'permissions',title:'授权管理'}]" :key="item.id" class="btn btn-sm" :class="{selected:tab===item.id}" @click="tab=item.id">{{ item.title }}</button><button class="btn btn-sm" :disabled="busy" @click="refresh">刷新</button></nav><p v-if="error" class="error" role="alert">{{ error }}</p>
 <div v-if="tab==='plan'"><p class="muted">可调整待执行步骤。保存后在下一次模型调用时采用；正在执行的操作不会被立即改写。</p><div v-for="(s,i) in steps" :key="s.id" class="plan-step"><span class="step-index">{{ i+1 }}</span><span class="step-state" :class="s.status">{{ statusLabel(s.status) }}</span><input v-if="s.status==='pending'&&!terminal()" v-model="s.title" class="field" maxlength="300" @input="dirty=true" /><span v-else class="step-title">{{ s.title }}</span><button v-if="s.status==='pending'&&!terminal()" class="btn btn-sm" :disabled="i===0||steps[i-1]?.status!=='pending'" @click="move(i)">上移</button><button v-if="s.status==='pending'&&!terminal()" class="btn btn-sm" @click="steps.splice(i,1);dirty=true">移除</button><button v-if="terminal()&&s.status!=='done'" class="btn btn-sm" :disabled="busy" @click="retry(s.id)">重试此步骤</button></div><p v-if="!steps.length" class="muted">尚未创建计划。复杂任务可让 Agent 自动拆分，也可在此添加。</p><form v-if="!terminal()" class="add-step" @submit.prevent="add"><input v-model="newStep" class="field" maxlength="300" placeholder="添加后续步骤" /><button class="btn">添加</button><button type="button" class="btn btn-primary" :disabled="busy||!steps.length" @click="save">保存计划</button></form><small v-else>重试会在同一会话创建只处理该步骤的新任务，原任务和日志保留；结果未知的操作须先核对。</small><details><summary>实际执行记录 · {{ actual.length }}</summary><div v-for="s in actual" :key="s.stepId" class="execution-row"><span>{{ s.ordinal }}. {{ s.description||s.kind }}</span><span>{{ statusLabel(s.status) }}</span></div></details></div>
 <div v-else-if="tab==='files'"><label class="btn btn-sm">{{ uploading?'导入中…':'导入资料（20MB以内）' }}<input type="file" hidden :disabled="uploading" accept=".pptx,.docx,.xlsx,.pdf,.txt,.md,.csv,.json,.png,.jpg,.jpeg,.zip" @change="uploadFile" /></label><p v-if="uploadNotice" role="status" class="muted">{{ uploadNotice }}</p><article v-for="b in batches" :key="b.id" class="batch"><h4>修改预览 · {{ b.status }}</h4><details v-for="f in parse(b.files)" :key="f.path"><summary>{{ f.path }}</summary><pre>{{ f.previewDiff||f.content }}</pre></details><button v-if="b.status==='draft'&&confirmBatch!==b.id" class="btn" :disabled="busy" @click="confirmBatch=b.id">批量确认这些修改</button><div v-if="confirmBatch===b.id"><p>将应用上述项目文件改动。已变化的文件会阻止应用，修改保留撤销记录。</p><button class="btn btn-primary" :disabled="busy" @click="act(()=>api.post('/api/operations/runs/'+runId+'/batches/'+b.id+'/apply')).then(()=>confirmBatch='')">确认应用</button><button class="btn" @click="confirmBatch=''">取消</button></div><small v-if="b.status==='needs_check'">批次未全部完成，请在项目面板检查已应用修改并按需撤销。</small></article><div v-for="f in files" :key="f.objectId" class="artifact-row"><span>{{ f.name }} <small>{{ (f.byteSize/1024).toFixed(1) }} KB</small></span><button class="btn btn-sm" @click="preview={id:f.objectId,name:f.name}">预览</button><button class="btn btn-sm" @click="downloadArtifact(f.objectId)">下载</button></div><p v-if="!files.length&&!batches.length" class="muted">暂无文件产物或待确认修改。</p><details class="export-form"><summary>生成正式文件</summary><label>标题<input v-model="title" class="field" maxlength="100" /></label><label>格式<select v-model="format" class="field"><option value="docx">Word (.docx)</option><option value="pdf">PDF</option><option value="xlsx">Excel (.xlsx)</option><option value="md">Markdown</option><option value="html">HTML 网页</option></select></label><label>{{ format==='xlsx'?'二维 JSON 数组，例如 [["名称","数量"],["示例",10]]':'正文（可编辑）' }}<textarea v-model="content" class="field" rows="7" maxlength="100000" /></label><button class="btn btn-primary" :disabled="exporting||!content.trim()||!title.trim()" @click="exportFile">{{ exporting?'生成中…':'生成并保存到任务' }}</button><small>Word / PDF 采用基础文本排版；网页预览隔离脚本与外部请求。完整文件可下载。</small></details></div>
 <div v-else-if="tab==='sources'"><h4>本次检索结果</h4><div v-for="(s,i) in sources.knowledge||[]" :key="i"><pre>{{ s.content }}</pre></div><p v-if="!sources.knowledge?.length" class="muted">此任务没有已记录的知识库检索结果。</p><h4>当前会话产生的长期记忆</h4><article v-for="(s,i) in sources.memories||[]" :key="i" class="source"><strong>{{ s.memory_key }}</strong><p>{{ s.content }}</p><blockquote>{{ s.evidence }}</blockquote><small>来源：{{ s.session_title||s.session_id }} · 消息 {{ s.source_seq }} · 版本 {{ s.memory_version }} · {{ s.state }}</small></article><p v-if="!sources.memories?.length" class="muted">没有本会话的记忆来源记录。跨会话的记忆可在工作台查看。</p></div>
 <div v-else><p class="muted">授权仅对当前任务生效。撤销后，后续调用重新申请；正在执行的命令请用“停止任务”中断。撤销联网或浏览器授权会关闭独立浏览器页面。</p><div v-for="p in permissions" :key="p.scope" class="permission-row"><span>{{ scopeLabel(p.scope) }}</span><small>{{ new Date(p.grantedAt).toLocaleString('zh-CN') }}</small><button class="btn btn-sm" :disabled="busy" @click="act(()=>api.del('/api/operations/runs/'+runId+'/permissions/'+p.scope))">撤销授权</button></div><p v-if="!permissions.length" class="muted">当前任务没有持有联网、终端或浏览器交互授权。</p><small>项目内文件访问来自你选择的项目目录；停用项目文件工具可在“工具与技能”中设置。</small></div>
 </div><ArtifactPreview v-if="preview" :key="preview.id" :id="preview.id" :name="preview.name" @close="preview=null" /></section></template>
<style scoped>.run-workspace{border:1px solid var(--line);border-radius:10px;background:var(--ink-2);margin:0 0 16px;font-size:12px}.workspace-toggle{display:flex;align-items:center;gap:16px;border:0;background:transparent;padding:12px 15px;color:var(--txt-2);width:100%;cursor:pointer;font:inherit}.workspace-toggle>span:last-child{margin-left:auto;font-size:11px}.workspace-toggle small{color:var(--txt-3);font-size:10px}.workspace-body{padding:0 18px 18px;border-top:1px solid var(--line)}nav{display:flex;gap:5px;padding:12px 0;flex-wrap:wrap}nav .selected{background:var(--amber-soft)}p,small{line-height:1.8}small{display:block;font-size:10px;color:var(--txt-3)}.plan-step,.permission-row,.artifact-row{display:flex;align-items:center;gap:8px;padding:10px 0;border-bottom:1px solid var(--line)}.plan-step .field,.step-title{flex:1;min-width:0;font-size:12px}.step-index{color:var(--txt-3);width:18px}.step-state{white-space:nowrap;color:var(--txt-3);font-size:10px}.step-state.doing{color:var(--green)}.step-state.failed,.error{color:var(--red)}.step-state.done{color:var(--green)}.add-step{display:flex;gap:7px;margin:14px 0}.add-step input{flex:1;min-width:0}.execution-row{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:8px;gap:10px}.artifact-row>span,.permission-row>span{flex:1}.export-form{border-top:1px solid var(--line);margin-top:16px;padding-top:14px}.export-form label{display:block;margin-top:12px;color:var(--txt-2)}.export-form .field{width:100%;margin:6px 0 10px}.batch,.source{padding:10px 0 16px;border-bottom:1px solid var(--line)}pre{max-height:350px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.8 var(--font-mono);padding:12px;background:var(--ink-1);border-radius:8px}details{margin-top:12px}summary{cursor:pointer;color:var(--txt-2)}blockquote{border-left:2px solid var(--line-strong);padding-left:12px;color:var(--txt-3)}h4{font-size:12px;margin:12px 0}</style>
